//
//	get <key>
//	set <key> <value>
//	delete <key>
//	size
func (a *AdminTool) Execute(line string) (string, error) {
	fields := strings.Fields(line)
	if len(fields) == 0 {
		return "", fmt.Errorf("empty command")
	}
	switch fields[0] {
	case "get":
		if len(fields) != 2 {
			return "", fmt.Errorf("usage: get <key>")
		}
		v, ok := a.cache.Get(fields[1])
		if !ok {
			return "<missing>", nil
		}
		return v, nil
	case "set":
		if len(fields) != 3 {
			return "", fmt.Errorf("usage: set <key> <value>")
		}
