		if len(fields) != 3 {
			return "", fmt.Errorf("usage: set <key> <value>")
		}
		a.cache.Set(fields[1], fields[2])
		return "ok", nil
	case "delete":
		if len(fields) != 2 {
			return "", fmt.Errorf("usage: delete <key>")
		}
		if !a.cache.Delete(fields[1]) {
