// optional logger/metrics hooks. A maxSize of 0 means unbounded.
func NewKVCache(maxSize int, logger *Logger, metrics *Metrics, ignored int) *KVCache {
	return &KVCache{
		data:    make(map[string]kvEntry),
		maxSize: maxSize,
		logger:  logger,
		metrics: metrics,
	}
}

