#!/usr/bin/env python3
"""Verify every exported top-level Go symbol in this directory has a doc
comment whose first line starts with "// <Name>".

Scans *.go (excluding *_test.go) in the current directory. Recognizes top-level
func, method, type, const, and var declarations whose identifier begins with
an uppercase letter. Exits non-zero on the first missing or malformed comment.
"""
import re
import sys
from pathlib import Path

PATTERNS = [
    re.compile(r"^func\s+(?:\([^)]+\)\s+)?([A-Z]\w*)\s*\("),
    re.compile(r"^type\s+([A-Z]\w*)\s"),
    re.compile(r"^const\s+([A-Z]\w*)\s*="),
    re.compile(r"^var\s+([A-Z]\w*)\s"),
]


def exported_name(line: str):
    for pat in PATTERNS:
        m = pat.match(line)
        if m:
            return m.group(1)
    return None


def check_file(path: Path):
    lines = path.read_text().splitlines()
    errors = []
    for i, line in enumerate(lines):
        name = exported_name(line)
        if name is None:
            continue
        if i == 0:
            errors.append(f"{path}:{i + 1}: exported {name!r} has no doc comment")
            continue
        prev = lines[i - 1].strip()
        if not prev.startswith(f"// {name}"):
            errors.append(
                f"{path}:{i + 1}: exported {name!r} doc comment missing or "
                f"does not start with '// {name}' (got: {prev!r})"
            )
    return errors


def main():
    root = Path(".")
    all_errors = []
    files = sorted(p for p in root.glob("*.go") if not p.name.endswith("_test.go"))
    if not files:
        print("no .go files found", file=sys.stderr)
        sys.exit(2)
    for go_file in files:
        all_errors.extend(check_file(go_file))
    if all_errors:
        for e in all_errors:
            print(e, file=sys.stderr)
        sys.exit(1)
    print("docstring check: all exported symbols documented")


if __name__ == "__main__":
    main()

